// SPDX-License-Identifier: GPL-3.0-or-later
//! WP-2I.03 acceptance (property): random sequences of the real document commands, a
//! checkpoint at a random point, more commands, then `edit.restore` gives exactly the
//! checkpointed document (structural equality), and `edit.undo` gives back the document from
//! before the restore. Commands are generated by the WP-1B.07 strategies
//! (`cutweave_ops::testing`) over every registered document command, with valid and invalid
//! params; the starting documents are `arb_project` documents and the WP-1B.06 shapes it makes.

#![allow(clippy::unwrap_used, clippy::expect_used)]

use std::sync::{Arc, LazyLock};

use cutweave_commands::{ActorCtx, ConnId, DocConfig, DocState, EntryKind, Registry, Submit};
use cutweave_model::Project;
use cutweave_ops::testing::{self, arb_command_from, check_invariants};
use proptest::{
    collection::vec,
    prelude::*,
    strategy::ValueTree,
    test_runner::{Config, RngAlgorithm, TestRng, TestRunner},
};
use serde_json::{Value, json};

static REGISTRY: LazyLock<Arc<Registry>> = LazyLock::new(|| Arc::new(testing::registry()));

fn splitmix(mut z: u64) -> u64 {
    z = z.wrapping_add(0x9E37_79B9_7F4A_7C15);
    z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
    z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
    z ^ (z >> 31)
}

/// The document command `seed` picks for `doc` (deterministic, so a shrunk case replays
/// exactly). Engine commands (transactions, history, jobs, import, export) are skipped: they
/// are not what a checkpoint restores.
fn generate(doc: &Project, seed: u64) -> (String, Value) {
    let mut seed = seed;
    loop {
        let (name, params) = generate_any(doc, seed);
        let kind = REGISTRY.get(&name).map(|e| e.meta.kind);
        if kind == Some(EntryKind::Command) {
            return (name, params);
        }
        seed = splitmix(seed);
    }
}

fn generate_any(doc: &Project, seed: u64) -> (String, Value) {
    let mut bytes = [0_u8; 32];
    let mut s = seed;
    for chunk in bytes.chunks_mut(8) {
        s = splitmix(s);
        chunk.copy_from_slice(&s.to_le_bytes());
    }
    let config = Config {
        failure_persistence: None,
        ..Config::default()
    };
    let mut runner =
        TestRunner::new_with_rng(config, TestRng::from_seed(RngAlgorithm::ChaCha, &bytes));
    arb_command_from(&REGISTRY, doc)
        .new_tree(&mut runner)
        .expect("the strategies never reject")
        .current()
}

fn actor(agent: bool) -> ActorCtx {
    if agent {
        ActorCtx::agent(ConnId::new(2), "prop").unwrap()
    } else {
        ActorCtx::ui(ConnId::new(1))
    }
}

/// Runs the generated commands (failures are part of the sequence and change nothing).
fn run_all(s: &mut DocState, seeds: &[(u64, bool)]) {
    for (seed, agent) in seeds {
        let (name, params) = generate(s.committed_doc(), *seed);
        let _ = s.submit(Submit::new(actor(*agent), name, params));
    }
}

proptest! {
    #![proptest_config(ProptestConfig { cases: 96, ..ProptestConfig::default() })]

    #[test]
    fn restore_gives_the_checkpointed_document_and_undo_takes_it_back(
        start in cutweave_model::testing::arb_project(),
        before in vec((any::<u64>(), prop::bool::weighted(0.3)), 0..25),
        after in vec((any::<u64>(), prop::bool::weighted(0.3)), 1..25),
        named in any::<bool>(),
    ) {
        let mut s = DocState::new(DocConfig::deterministic(Arc::clone(&REGISTRY), start, 42));
        run_all(&mut s, &before);
        let params = if named { json!({"name": "here"}) } else { json!({}) };
        let made = s.submit(Submit::new(actor(true), "edit.checkpoint", params)).unwrap();
        let id = made.output["checkpoint"].as_str().unwrap().to_owned();
        let checkpointed = s.committed_doc().clone();
        run_all(&mut s, &after);
        let before_restore = s.committed_doc().clone();

        // `force`: the sequence mixes the person's and the agent's changes.
        let restored = s
            .submit(Submit::new(actor(true), "edit.restore", json!({"checkpoint": id, "force": true})))
            .unwrap();
        prop_assert_eq!(s.committed_doc(), &checkpointed);
        check_invariants(s.committed_doc()).map_err(TestCaseError::fail)?;
        if restored.output["tx"].is_null() {
            prop_assert_eq!(&before_restore, &checkpointed);
        } else {
            s.submit(Submit::new(actor(true), "edit.undo", json!({}))).unwrap();
            prop_assert_eq!(s.committed_doc(), &before_restore);
        }
        s.verify().map_err(TestCaseError::fail)?;
    }
}
